package app.orbit.couple;
import android.content.Context;
import android.graphics.*;
import org.json.*;
import java.io.*;
import java.net.*;
import java.text.DateFormat;
import java.util.*;
final class WidgetEngine {
    interface Active{boolean get();}
    static boolean privateMode(Context c){var p=c.getSharedPreferences("orbit-privacy",0);return p.getBoolean("lock",false)||p.getBoolean("screenshots",false);}
    static String uid(Context c)throws Exception{String raw=TrackerAuth.read(c);if(raw==null)throw new Exception("ACCOUNT_CHANGED");String uid=new JSONObject(raw).getJSONObject("user").getString("id");var prefs=c.getSharedPreferences("OrbitAuth",0);if(!uid.equals(prefs.getString("owner","")))prefs.edit().putString("owner",uid).commit();return uid;}
    private static JSONObject row(Context c,String owner,String path)throws Exception{TrackerAuth.Reply reply=TrackerAuth.requestAs(c,owner,"GET",path,null);if(reply.status()!=200)throw new Exception("WIDGET_UNAVAILABLE");JSONArray rows=new JSONArray(reply.body());if(rows.length()!=1)throw new Exception("WIDGET_REMOVED");return rows.getJSONObject(0);}
    private static JSONObject photo(Context c,String owner,String couple,String id)throws Exception{return row(c,owner,"/rest/v1/posts?id=eq."+id+"&couple_id=eq."+couple+"&keep=eq.true&unsent_at=is.null&kind=eq.photo&select=id,archive_revision,thumb_path,media_path");}
    static void select(Context c,String owner,String couple,String kind,String id,long version,Active active)throws Exception{
        synchronized(TrackerAuth.class){if(!uid(c).equals(owner)||!active.get())throw new Exception("ACCOUNT_CHANGED");OutboxFiles.uuid(owner);OutboxFiles.uuid(couple);OutboxFiles.uuid(id);String epoch=WidgetStore.generation(c);
            JSONObject membership=row(c,owner,"/rest/v1/members?user_id=eq."+owner+"&couple_id=eq."+couple+"&select=user_id");if(!membership.getString("user_id").equals(owner))throw new Exception("ACCOUNT_CHANGED");
            WidgetSnapshot item;
            if(kind.equals("photo")){JSONObject post=photo(c,owner,couple,id);long revision=post.getLong("archive_revision");if(version!=revision)throw new Exception("WIDGET_CHANGED");String path=post.optString("thumb_path","");if(path.isEmpty()||path.equals("null"))path=post.getString("media_path");byte[] image=null;try{WidgetSnapshot cached=WidgetStore.read(c);if(cached.owner.equals(owner)&&cached.couple.equals(couple)&&cached.id.equals(id)&&cached.revision==revision&&cached.kind.equals("photo"))image=cached.image;}catch(Exception ignored){}if(image==null)image=image(c,owner,couple,path);if(photo(c,owner,couple,id).getLong("archive_revision")!=revision)throw new Exception("WIDGET_CHANGED");item=new WidgetSnapshot(owner,couple,kind,id,revision,System.currentTimeMillis(),0,"Kept photo","",image);
            }else if(kind.equals("plan")){JSONObject plan=row(c,owner,"/rest/v1/plans?id=eq."+id+"&couple_id=eq."+couple+"&cancelled=eq.false&select=id,title,starts_at,timezone,version");long revision=plan.getLong("version"),starts=WidgetSnapshot.instant(plan.getString("starts_at"));if((version>=0&&version!=revision)||starts<=System.currentTimeMillis())throw new Exception("WIDGET_CHANGED");String zone=plan.getString("timezone");if(!Arrays.asList(TimeZone.getAvailableIDs()).contains(zone))throw new Exception("WIDGET_UNAVAILABLE");DateFormat date=DateFormat.getDateTimeInstance(DateFormat.MEDIUM,DateFormat.SHORT);date.setTimeZone(TimeZone.getTimeZone(zone));item=new WidgetSnapshot(owner,couple,kind,id,revision,System.currentTimeMillis(),starts,plan.getString("title"),date.format(new Date(starts)),new byte[0]);
            }else throw new Exception("WIDGET_UNAVAILABLE");
            if(!active.get()||!uid(c).equals(owner))throw new Exception("ACCOUNT_CHANGED");WidgetStore.put(c,item,epoch);
        }
    }
    static void refresh(Context c,Active active){synchronized(TrackerAuth.class){var p=WidgetStore.prefs(c);String owner=p.getString("owner",""),couple=p.getString("couple",""),kind=p.getString("kind",""),id=p.getString("id","");if(owner.isEmpty()||privateMode(c)||!active.get())return;try{select(c,owner,couple,kind,id,kind.equals("photo")?p.getLong("revision",0):-1,()->active.get()&&!privateMode(c));}catch(Exception unavailable){if(active.get()){String code=unavailable.getMessage();if("WIDGET_REMOVED".equals(code)||"WIDGET_CHANGED".equals(code))WidgetStore.clear(c);else if(!"WIDGET_CANCELLED".equals(code))WidgetStore.invalidate(c);}}}}
    private static byte[] image(Context c,String owner,String couple,String path)throws Exception{
        if(!path.startsWith(couple+"/")||!path.matches("[a-z0-9/_.-]+"))throw new Exception("WIDGET_UNAVAILABLE");TrackerAuth.Reply signed=TrackerAuth.requestAs(c,owner,"POST","/storage/v1/object/sign/media/"+path,new JSONObject().put("expiresIn",120));if(signed.status()!=200)throw new Exception("WIDGET_UNAVAILABLE");String relative=signed.json().getString("signedURL");if(!relative.startsWith("/object/sign/media/"+path+"?"))throw new Exception("WIDGET_UNAVAILABLE");String base=c.getSharedPreferences("OrbitTracking",0).getString("url","");URL url=new URL(base+"/storage/v1"+relative);if(!url.getProtocol().equals("https")||!url.getHost().equals(new URL(base).getHost()))throw new Exception("WIDGET_UNAVAILABLE");
        HttpURLConnection request=(HttpURLConnection)url.openConnection();byte[] raw;try{request.setConnectTimeout(12000);request.setReadTimeout(12000);request.setInstanceFollowRedirects(false);if(request.getResponseCode()!=200)throw new Exception("WIDGET_UNAVAILABLE");try(InputStream in=request.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] buffer=new byte[8192];int n;while((n=in.read(buffer))!=-1){if(out.size()+n>1024*1024)throw new Exception("WIDGET_UNAVAILABLE");out.write(buffer,0,n);}raw=out.toByteArray();}}finally{request.disconnect();}
        BitmapFactory.Options bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(raw,0,raw.length,bounds);if(bounds.outWidth<1||bounds.outHeight<1||bounds.outWidth>4096||bounds.outHeight>4096)throw new Exception("WIDGET_UNAVAILABLE");BitmapFactory.Options options=new BitmapFactory.Options();options.inSampleSize=1;while(Math.max(bounds.outWidth,bounds.outHeight)/options.inSampleSize>640)options.inSampleSize*=2;
        Bitmap decoded=BitmapFactory.decodeByteArray(raw,0,raw.length,options);if(decoded==null)throw new Exception("WIDGET_UNAVAILABLE");Bitmap scaled=null;try{float ratio=Math.min(1f,Math.min(320f/decoded.getWidth(),240f/decoded.getHeight()));scaled=Bitmap.createScaledBitmap(decoded,Math.max(1,Math.round(decoded.getWidth()*ratio)),Math.max(1,Math.round(decoded.getHeight()*ratio)),true);ByteArrayOutputStream out=new ByteArrayOutputStream();if(!scaled.compress(Bitmap.CompressFormat.WEBP,78,out)||out.size()>WidgetSnapshot.MAX_IMAGE)throw new Exception("WIDGET_UNAVAILABLE");return out.toByteArray();}finally{if(scaled!=null&&scaled!=decoded)scaled.recycle();decoded.recycle();}
    }
}
